text:
.diff-session-workflow { margin: 8px 0 14px; padding: var(--space-4); border: 1px solid var(--border-color, var(--text-primary)); border-radius: var(--radius-lg); }
.diff-session-workflow summary { cursor: pointer; }
.diff-session-workflow fieldset { padding: 0; border: 0; min-width: 0; }
.diff-session-workflow label { display: grid; gap: var(--space-2); margin: 10px 0; }
.diff-session-workflow input, .diff-session-workflow select, .diff-session-workflow textarea { width: 100%; box-sizing: border-box; min-width: 0; font: inherit; }
.diff-session-workflow textarea { min-height: 70px; resize: vertical; }
.diff-session-workflow p, .diff-session-workflow small { font-size: var(--text-md); overflow-wrap: anywhere; }
.diff-session-workflow button { margin: 4px 6px 4px 0; }
